import jwt from 'jsonwebtoken';
import { randomBytes, createHash } from 'node:crypto';

// ── 1. JWT: issue and verify access tokens ────────────────────
const JWT_SECRET = process.env.JWT_SECRET; // minimum 32 bytes of entropy

function issueAccessToken(userId, roles) {
  return jwt.sign(
    { sub: userId, roles },
    JWT_SECRET,
    {
      expiresIn: '15m',            // Short-lived: 15 minutes
      issuer: 'api.example.com',   // Who created the token
      audience: 'web-app',         // Who should accept the token
    }
  );
}

function verifyAccessToken(token) {
  try {
    // Explicitly pass expected issuer and audience — prevents tokens
    // issued for service A from being accepted by service B
    return jwt.verify(token, JWT_SECRET, {
      algorithms: ['HS256'],       // Whitelist: never accept 'none'
      issuer: 'api.example.com',
      audience: 'web-app',
    });
  } catch {
    return null;                   // Never expose error detail to client
  }
}

const token = issueAccessToken('user-123', ['editor']);
const payload = verifyAccessToken(token);
console.log('Verified payload:', payload);
// { sub: 'user-123', roles: ['editor'], exp: ..., iat: ..., iss: '...', aud: '...' }

// ── 2. RBAC middleware (Express-style) ───────────────────────
const ROLE_PERMISSIONS = {
  admin:  ['read:any', 'write:any', 'delete:any'],
  editor: ['read:any', 'write:own'],
  viewer: ['read:any'],
};

function requirePermission(permission) {
  return (req, res, next) => {
    // Step 1: AuthN — extract and verify the token
    const authHeader = req.headers.authorization;
    if (!authHeader?.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Authentication required' });
    }
    const payload = verifyAccessToken(authHeader.slice(7));
    if (!payload) {
      return res.status(401).json({ error: 'Invalid or expired token' });
    }

    // Step 2: AuthZ — check permissions
    const userPerms = (payload.roles ?? [])
      .flatMap(role => ROLE_PERMISSIONS[role] ?? []);
    if (!userPerms.includes(permission)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    req.user = payload; // Pass verified identity to route handlers
    next();
  };
}

// Usage:
// app.get('/articles',        requirePermission('read:any'),   listArticles);
// app.post('/articles',       requirePermission('write:own'),  createArticle);
// app.delete('/articles/:id', requirePermission('delete:any'), deleteArticle);

// ── 3. PKCE generation for SPA / mobile OAuth flows ──────────
function generatePKCE() {
  const verifier  = randomBytes(32).toString('base64url');  // Store this locally
  const challenge = createHash('sha256')
    .update(verifier)
    .digest('base64url');                                   // Send this to AS
  const state     = randomBytes(16).toString('hex');        // CSRF nonce
  return { verifier, challenge, state };
}

const pkce = generatePKCE();
console.log('code_challenge (send to AS):', pkce.challenge);
console.log('code_verifier (keep secret):', pkce.verifier.slice(0, 10) + '...');

import bcrypt from 'bcrypt';
import { timingSafeEqual, randomBytes } from 'node:crypto';

// ── 1. Password hashing and verification with bcrypt ─────────
const BCRYPT_ROUNDS = 12; // ~250ms per hash on modern hardware — adjust as CPUs get faster

async function hashPassword(plaintext) {
  return bcrypt.hash(plaintext, BCRYPT_ROUNDS);
  // bcrypt internally generates and embeds a random salt
  // output: '$2b$12$<22-char-salt><31-char-hash>'
}

async function verifyPassword(plaintext, storedHash) {
  // bcrypt.compare is constant-time — safe against timing attacks
  return bcrypt.compare(plaintext, storedHash);
}

// ── 2. Timing-safe login handler ─────────────────────────────
async function loginHandler(email, password, userStore) {
  const user = await userStore.findByEmail(email);

  if (!user) {
    // Perform a dummy compare to equalize response time:
    // Without this, response time reveals whether the email exists
    await bcrypt.compare(password, '$2b$12$invalidhashfillerthatislong12345678');
    return { success: false, error: 'Invalid credentials' };
  }

  const valid = await verifyPassword(password, user.passwordHash);
  if (!valid) {
    return { success: false, error: 'Invalid credentials' };
  }

  return { success: true, userId: user.id };
}

// ── 3. IDOR protection — ownership check ─────────────────────
async function getInvoice(req, res, invoiceStore) {
  const invoiceId = req.params.id;
  const invoice = await invoiceStore.findById(invoiceId);

  if (!invoice) {
    return res.status(404).json({ error: 'Not found' });
  }

  // CRITICAL: RBAC check alone is not enough.
  // Verify the authenticated user owns this specific resource.
  if (invoice.ownerId !== req.user.sub) {
    // Return 404 rather than 403 to avoid confirming the invoice exists
    return res.status(404).json({ error: 'Not found' });
  }

  return res.json(invoice);
}

// ── 4. Secure API key generation and verification ─────────────
function generateApiKey() {
  const prefix  = 'sk_live_';                          // Namespace for scanning/rotation
  const entropy = randomBytes(24).toString('base64url'); // 192 bits
  return prefix + entropy;
}

async function verifyApiKey(submittedKey, storedKeyHash) {
  // Hash the submitted key (same algorithm as at creation)
  const submittedHash = await bcrypt.hash(submittedKey, BCRYPT_ROUNDS);
  // timingSafeEqual prevents timing attacks on string comparison
  const a = Buffer.from(submittedHash);
  const b = Buffer.from(storedKeyHash);
  if (a.length !== b.length) return false;
  return timingSafeEqual(a, b);
}
